def from_specification(spec):
    if spec["evaluation_points"] != "1,...,N modulo prime":
        raise ValueError("evaluation convention mismatch")
    problem = PrimeCharacterOPI(int(spec["prime_decimal"]), spec["RS_dimension"], spec["power_index"],
                               int(spec["coset_generator_decimal"]), tuple(map(int, spec["shifts_decimal"])),
                               tuple(spec["coset_orientations"]), spec["generator_search_trials"], spec["include_zero"])
    if problem.specification() != spec:
        raise ValueError("noncanonical native character specification")
    return problem


def instance(prime, length, dimension, exponent, seed, *, mode="mixed", include_zero=True):
    ring(prime)
    prime_divisors(exponent)
    integer(length, "RS positions", 1, min(4096, prime-1))
    integer(dimension, "RS dimension", 1, length)
    integer(seed, "public replay seed", 0, (1 << 64)-1)
    if (prime-1) % exponent or mode not in ("global", "mixed"):
        raise ValueError("dividing power index and explicit source mode required")
    rng = random.Random(seed)
    for trials in range(1, 257):
        g = rng.randrange(1, prime)
        if generator_valid(prime, exponent, g):
            break
    else:
        raise RuntimeError("UNKNOWN: bounded coset-generator search, no source admitted")
    # Paired global/mixed instances keep IDENTICAL shifts. No factorization of p-1.
    shifts = tuple(rng.randrange(prime) for _ in range(length))
    orientations = (0,)*length if mode == "global" else tuple(rng.randrange(exponent) for _ in range(length))
    return PrimeCharacterOPI(prime, dimension, exponent, g, shifts, orientations, trials, include_zero)


def interpolate(prime, points, values):
    """Lagrange interpolation using FLINT polynomial products and exact division."""
    C, V = ring(prime), ring(prime)([1])
    if len(points) != len(values) or len(set(points)) != len(points):
        raise ValueError("distinct interpolation points and matching values required")
    for x in points:
        V *= C([-x, 1])
    derivative, T = V.derivative(), C([])
    for x, y in zip(points, values):
        quotient, remainder = divmod(V, C([-x, 1]))
        if not remainder.is_zero():
            raise ArithmeticError("native vanishing polynomial division failed")
        T += quotient*(y*pow(int(derivative(x)), -1, prime) % prime)
    return T, V


def root_at_infinity(prime, polynomial, exponent, degree, leading=1):
    """Monic-normalized formal r-th root, truncated with FLINT series inverses."""
    if exponent % prime == 0 or polynomial.degree() != exponent*degree:
        raise ValueError("invertible root index and exact divisible leading degree required")
    integer(leading, "nonzero chosen root leading coefficient", 1, prime-1)
    if int(polynomial[exponent*degree]) != pow(leading, exponent, prime):
        raise ValueError("declared leading root does not match polynomial")
    C, inverse = ring(prime), pow(exponent, -1, prime)
    reversed_F = polynomial.reverse(degree=exponent*degree)*pow(pow(leading, exponent, prime), -1, prime)
    B, precision, steps = C([1]), 1, []
    while precision < degree+1:
        precision = min(2*precision, degree+1)
        reciprocal = B.pow_trunc(exponent-1, precision).inverse_series_trunc(precision)
        B = ((exponent-1)*B+reversed_F*reciprocal).truncate(precision)*inverse
        if not B.pow_trunc(exponent, precision).equal_trunc(reversed_F, precision):
            raise ArithmeticError("formal Newton root congruence failed")
        steps.append(precision)
    R = B.reverse(degree=degree)*leading
    if (R**exponent-polynomial).degree() >= (exponent-1)*degree:
        raise ArithmeticError("formal root failed its exact degree-cancellation certificate")
    return R, {"truncation_precisions": steps, "series_inverse_calls": len(steps),
               "truncated_polynomial_powers_including_checks": 2*len(steps),
               "leading_root_decimal": str(leading)}


def complete_positions(problem, positions, *, leading=1):
    """Q=T+beta*(R^r-leading^r X^padding V) on a COMMON power coset."""
    if (type(positions) is not tuple or not positions or len(set(positions)) != len(positions)
            or any(type(i) is not int or not 0 <= i < problem.length for i in positions)):
        raise ValueError("nonempty distinct native positions required")
    p, r, C = problem.prime, problem.exponent, ring(problem.prime)
    points = tuple(i+1 for i in positions)
    interpolation_values = tuple(problem.shifts[i] if problem.include_zero else
                                 (problem.shifts[i]+problem.multiplier(i)) % p for i in positions)
    if len(positions) <= problem.dimension:
        T, V = interpolate(p, points, interpolation_values)
        Q, root_record = T, None
        degree_threshold = len(positions)
    else:
        T, V = interpolate(p, points, tuple(problem.shifts[i] for i in positions))
        if len({problem.orientations[i] for i in positions}) != 1:
            return {"status": "NOT_APPLICABLE_MIXED_POWER_COSETS", "original_problem_unsatisfiable": False}
        D = (len(positions)+r-1)//r
        degree_threshold = (r-1)*D+int(not problem.include_zero)
        if degree_threshold > problem.dimension:
            return {"status": "NOT_APPLICABLE_DEGREE_BUDGET", "original_problem_unsatisfiable": False}
        beta = problem.multiplier(positions[0])
        W = (C.gen()**(r*D-len(positions)))*V*pow(leading, r, p)
        R, root_record = root_at_infinity(p, W-T*pow(beta, -1, p), r, D, leading)
        if not problem.include_zero:
            base_coefficients = [str(a) for a in R.coeffs()]
            forbidden = {-int(R(x)) % p for x in points}
            shift = next(c for c in range(len(points)+1) if c not in forbidden)
            R += shift
            root_record.update({"base_root_polynomial_coefficients_decimal": base_coefficients,
                                "series_congruence_applies_to_base_root": True,
                                "zero_avoidance_shift_decimal": str(shift),
                                "zero_avoidance_root_evaluations_charged": len(points),
                                "zero_avoidance_candidate_shifts_tested": shift+1,
                                "distinct_forbidden_shifts": len(forbidden),
                                "candidate_shift_search_bounded_by_selected_points_plus_one": True,
                                "field_size_scan_required_for_zero_avoidance": False})
        Q = T+beta*(R**r-W)
        for x, i in zip(points, positions):
            if int(Q(x)) != (problem.shifts[i]+beta*pow(int(R(x)), r, p)) % p:
                raise ArithmeticError("power lift identity failed at a native point")
        root_record.update({"root_polynomial_coefficients_decimal": [str(a) for a in R.coeffs()],
                            "common_coset_orientation": problem.orientations[positions[0]]})
    if Q.degree() >= problem.dimension:
        raise ArithmeticError("completion exceeds native RS degree")
    coefficients = tuple(map(int, Q.coeffs()))
    values = problem.evaluations(coefficients)
    if not all(problem.accepted(i, values[i]) for i in positions):
        raise ArithmeticError("independent integer Horner rejects a forced position")
    return {"status": "NATIVE_COMPLETION_WITNESS", "polynomial_coefficients_decimal": list(map(str, coefficients)),
            "degree": Q.degree(), "proved_degree_dimension_threshold": degree_threshold,
            "forced_positions": list(positions), "score_count": sum(problem.accepted(i, y) for i, y in enumerate(values)),
            "formal_root_certificate": root_record, "interpolation_points_charged": len(points),
            "native_Horner_evaluations": problem.length, "full_field_table_materialized": False,
            "native_membership_tests_including_forced_checks": problem.length+len(positions),
            "FLINT_polynomial_divisions_in_interpolation": len(points),
            "operation_counts_are_not_a_full_bit_or_quantum_gate_budget": True,
            "original_problem_unsatisfiable": False}


def quadratic_jet_attack(problem, seed, *, max_root_trials=256):
    """Use free low root coefficients to force additional signed-residue constraints.

    For nonzero a, at least (p-1)/2 values z make a+beta*z^2 lie in a
    specified quadratic coset (including zero). Handle a=0 directly. Search
    caps are UNKNOWN, not source rejection or unsatisfiability.
    """
    if problem.exponent != 2:
        raise ValueError("local conic-value guarantee established only for quadratic characters")
    if not problem.include_zero:
        raise ValueError("zero-including predicates required by this jet baseline")
    integer(seed, "quadratic jet seed", 0, (1 << 64)-1)
    integer(max_root_trials, "local residue search budget", 0, 1024)
    p, K, N, C = problem.prime, problem.dimension, problem.length, ring(problem.prime)
    rng = random.Random(seed)
    buckets = [tuple(i for i, orientation in enumerate(problem.orientations) if orientation == j) for j in range(2)]
    largest = max(buckets, key=len)
    M = min(2*K, len(largest))
    positions = tuple(rng.sample(largest, M))
    D = max((M+1)//2, K//2)
    protected = max(0, 2*D-K+1)
    free = D-protected+1
    leading, beta = rng.randrange(1, p), problem.multiplier(positions[0])
    T, V = interpolate(p, tuple(i+1 for i in positions), tuple(problem.shifts[i] for i in positions))
    W = C.gen()**(2*D-M)*V*(leading*leading % p)
    R0, root_record = root_at_infinity(p, W-T*pow(beta, -1, p), 2, D, leading)
    outside = [i for i in range(N) if i not in positions]
    rng.shuffle(outside)
    extra, values, unknown = [], [], []
    proposals = direct = 0
    for i in outside[:free]:
        x = i+1
        a = (int(T(x))-beta*int(W(x))-problem.shifts[i]) % p
        z = None
        if a == 0:
            z, direct = 0, direct+1
        else:
            for _ in range(max_root_trials):
                trial = rng.randrange(p)
                proposals += 1
                if problem.accepted(i, (problem.shifts[i]+a+beta*trial*trial) % p):
                    z = trial
                    break
        if z is None:
            unknown.append(i)
            continue
        extra.append(i)
        values.append((z-int(R0(x))) % p)
    L = interpolate(p, tuple(i+1 for i in extra), tuple(values))[0] if extra else C([])
    if L.degree() >= free:
        raise ArithmeticError("jet interpolation changed protected high root coefficients")
    R = R0+L
    Q = T+beta*(R**2-W)
    if Q.degree() >= K:
        raise ArithmeticError("free root jet exceeded native RS degree")
    coefficients = tuple(map(int, Q.coeffs()))
    native = problem.evaluations(coefficients)
    forced = (*positions, *extra)
    if not all(problem.accepted(i, native[i]) for i in forced):
        raise ArithmeticError("quadratic jet failed independently verified native constraints")
    return {"status": "NATIVE_QUADRATIC_JET_WITNESS", "mechanism": "quadratic_jet",
            "attack_seed": seed, "polynomial_coefficients_decimal": list(map(str, coefficients)),
            "score_count": sum(problem.accepted(i, y) for i, y in enumerate(native)),
            "degree": Q.degree(), "forced_positions": list(forced),
            "common_coset_positions": list(positions), "extra_interpolated_positions": extra,
            "root_degree": D, "protected_high_root_coefficients": protected, "free_root_coefficients": free,
            "root_perturbation_coefficients_decimal": [str(a) for a in L.coeffs()],
            "base_root_coefficients_decimal": [str(a) for a in R0.coeffs()],
            "base_formal_root_certificate": root_record,
            "local_random_root_proposals": proposals, "local_zero_offset_direct_assignments": direct,
            "UNKNOWN_local_search_caps": unknown, "local_search_budget": max_root_trials,
            "IID_uniform_proposal_cap_union_bound": str(min(Fraction(1), len(outside[:free])*Fraction(2, 3)**max_root_trials)),
            "cap_bound_is_ensemble_not_seeded_PRNG_confidence": True,
            "native_Horner_evaluations": N,
            "native_membership_tests_including_forced_checks": N+len(forced)+proposals,
            "FLINT_polynomial_divisions_in_interpolations": M+len(extra),
            "operation_counts_are_not_a_full_bit_or_quantum_gate_budget": True,
            "source_rejected_or_resampled": False,
            "full_field_table_materialized": False, "classical_hardness_inferred": False}


def repair_quadratic_jet(problem, initial, seed, *, proposals_per_coordinate=8, max_passes=None):
    """Adaptive root-value exchanges; bounded sampling is NOT local optimality.

    A Lagrange basis on the extra coordinates changes only the released root
    value. Its degree remains below the free-jet budget, so common-coset
    constraints and the native code degree survive every exchange.
    """
    if problem.exponent != 2 or not problem.include_zero or initial.get("status") != "NATIVE_QUADRATIC_JET_WITNESS":
        raise ValueError("native quadratic jet witness required")
    integer(seed, "adaptive jet seed", 0, (1 << 64)-1)
    integer(proposals_per_coordinate, "paid proposals per released root", 0, 128)
    p, N, K, C = problem.prime, problem.length, problem.dimension, ring(problem.prime)
    positions = tuple(initial["common_coset_positions"])
    extras = tuple(initial["extra_interpolated_positions"])
    forced = positions+extras
    if (not positions or len(set(forced)) != len(forced)
            or any(type(i) is not int or not 0 <= i < N for i in forced)
            or len({problem.orientations[i] for i in positions}) != 1):
        raise ValueError("distinct native common/extra positions required")
    D, free = initial["root_degree"], initial["free_root_coefficients"]
    integer(D, "root degree", 1, K)
    integer(free, "free root coefficients", 0, D+1)
    if len(extras) > free or 2*D-len(positions) < 0:
        raise ValueError("invalid jet dimensions")
    T, V = interpolate(p, tuple(i+1 for i in positions), tuple(problem.shifts[i] for i in positions))
    leading = int(initial["base_formal_root_certificate"]["leading_root_decimal"])
    beta = problem.multiplier(positions[0])
    W = C.gen()**(2*D-len(positions))*V*(leading*leading % p)
    R0 = C(list(map(int, initial["base_root_coefficients_decimal"])))
    perturbation = C(list(map(int, initial["root_perturbation_coefficients_decimal"])))
    if (R0.degree() != D or perturbation.degree() >= free
            or (R0**2-(W-T*pow(beta, -1, p))).degree() >= D
            or (free and D+free-1 >= K)):
        raise ValueError("invalid protected root or degree cancellation")
    root = R0+perturbation
    Q = T+beta*(root**2-W)
    coefficients = tuple(map(int, Q.coeffs()))
    if (list(map(str, coefficients)) != initial["polynomial_coefficients_decimal"]
            or Q.degree() >= K):
        raise ValueError("jet does not reconstruct its native polynomial")
    values = problem.evaluations(coefficients)
    accepted = tuple(problem.accepted(i, y) for i, y in enumerate(values))
    score = sum(accepted)
    if score != initial["score_count"] or not all(accepted[i] for i in forced):
        raise ValueError("initial jet fails native score or forced predicates")
    initial_score, rng = score, random.Random(seed)
    allowed = N-score+1 if max_passes is None else max_passes
    integer(allowed, "adaptive pass budget", 0, N+1)
    # Precompute directions once; no full-field value tables or source rerolls.
    directions = []
    for j in range(len(extras)):
        direction, _ = interpolate(p, tuple(i+1 for i in extras), tuple(int(j == k) for k in range(len(extras))))
        if direction.degree() >= free:
            raise ArithmeticError("exchange changes protected root coefficients")
        directions.append(direction)
    transcript, moves, passes, horner, membership = [], [], 0, N, N
    termination = "UNKNOWN_PASS_CAP"
    if score == N:
        termination = "PERFECT_NATIVE_WITNESS"
    elif not extras:
        termination = "NO_FREE_JET_COORDINATES"
    else:
        for pass_index in range(allowed):
            passes += 1
            before = score
            for e, direction in zip(extras, directions):
                for _ in range(proposals_per_coordinate):
                    delta = rng.randrange(p)
                    proposed_root_value = (int(root(e+1))+delta) % p
                    proposed_value = (int(T(e+1))+beta*(proposed_root_value**2-int(W(e+1)))) % p
                    feasible = problem.accepted(e, proposed_value)
                    membership += 1
                    proposal = {"pass": pass_index, "released_position": e, "delta_decimal": str(delta),
                                "released_predicate_accepted": feasible, "proposed_score": None,
                                "strict_improvement_accepted": False}
                    if feasible:
                        new_root = root+delta*direction
                        new_Q = T+beta*(new_root**2-W)
                        if new_Q.degree() >= K:
                            raise ArithmeticError("adaptive exchange exceeds native degree")
                        new_coefficients = tuple(map(int, new_Q.coeffs()))
                        new_values = problem.evaluations(new_coefficients)
                        new_accepted = tuple(problem.accepted(i, y) for i, y in enumerate(new_values))
                        horner, membership = horner+N, membership+N
                        if not all(new_accepted[i] for i in forced):
                            raise ArithmeticError("adaptive exchange lost a forced predicate")
                        proposal["proposed_score"] = sum(new_accepted)
                        if sum(new_accepted) > score:
                            root, Q, coefficients, score = new_root, new_Q, new_coefficients, sum(new_accepted)
                            proposal["strict_improvement_accepted"] = True
                            moves.append({"proposal_index": len(transcript), "score_count": score,
                                          "polynomial_coefficients_decimal": list(map(str, coefficients))})
                    transcript.append(proposal)
                    if score == N:
                        break
                if score == N:
                    break
            if score == N:
                termination = "PERFECT_NATIVE_WITNESS"
                break
            if score == before:
                termination = "NO_SAMPLED_IMPROVEMENT"
                break
    return {"status": "NATIVE_ADAPTIVE_QUADRATIC_JET_WITNESS", "mechanism": "adaptive_quadratic_jet",
            "attack_seed": seed, "proposals_per_coordinate": proposals_per_coordinate,
            "pass_budget": allowed, "passes_executed": passes, "termination": termination,
            "initial_score_count": initial_score, "score_count": score,
            "polynomial_coefficients_decimal": list(map(str, coefficients)), "degree": Q.degree(),
            "final_root_coefficients_decimal": [str(a) for a in root.coeffs()],
            "forced_positions": list(forced), "proposals": transcript, "accepted_moves": moves,
            "native_Horner_evaluations": horner, "native_membership_tests": membership,
            "FLINT_polynomial_divisions_in_setup": len(positions)+len(extras)**2,
            "all_proposals_retained": True, "local_or_global_optimality_proved": score == N,
            "source_rejected_or_resampled": False, "full_field_table_materialized": False,
            "classical_hardness_inferred": False,
            "operation_counts_are_not_a_full_bit_or_quantum_gate_budget": True}


def attack(problem, seed=0, *, trials=8):
    integer(seed, "attack replay seed", 0, (1 << 64)-1)
    integer(trials, "paid completion trials", 1, 64)
    rng, records = random.Random(seed), []
    linear = complete_positions(problem, tuple(range(problem.dimension)))
    buckets = [tuple(i for i, orientation in enumerate(problem.orientations) if orientation == j)
               for j in range(problem.exponent)]
    available = min(problem.length, problem.exponent*((problem.dimension-int(not problem.include_zero))//(problem.exponent-1)))
    largest = max(buckets, key=len)
    forced_count = max(problem.dimension, min(available, len(largest)))
    for _ in range(trials):
        if forced_count > problem.dimension:
            positions = tuple(rng.sample(largest, forced_count))
        else:
            positions = tuple(rng.sample(range(problem.length), problem.dimension))
        record = complete_positions(problem, positions, leading=rng.randrange(1, problem.prime))
        if record["status"] != "NATIVE_COMPLETION_WITNESS":
            raise ArithmeticError("internally selected completion is not applicable")
        record["mechanism"] = "power_completion"
        records.append(record)
    if problem.exponent == 2 and problem.include_zero:
        records.extend(quadratic_jet_attack(problem, rng.getrandbits(64)) for _ in range(trials))
    best = max(range(len(records)), key=lambda j: records[j]["score_count"])
    repair = None
    repair_start = None
    if problem.exponent == 2 and problem.include_zero:
        repair_start = max(range(trials, 2*trials), key=lambda j: records[j]["score_count"])
        repair = repair_quadratic_jet(problem, records[repair_start], rng.getrandbits(64))
    score = max(linear["score_count"], records[best]["score_count"])
    mechanism = "linear_interpolation" if linear["score_count"] > records[best]["score_count"] else records[best]["mechanism"]
    if repair is not None and repair["score_count"] > score:
        score, mechanism = repair["score_count"], repair["mechanism"]
    return {"attack_seed": seed, "trials": records, "best_trial_index": best,
            "linear_interpolation_baseline": linear,
            "adaptive_quadratic_jet_repair": repair, "repair_initial_trial_index": repair_start,
            "best_score_count": score, "best_witness_source": mechanism,
            "requested_trials_per_mechanism": trials, "power_completion_forced_count": forced_count,
            "total_native_Horner_evaluations": linear["native_Horner_evaluations"]+sum(row["native_Horner_evaluations"] for row in records)+(repair["native_Horner_evaluations"] if repair else 0),
            "single_power_completion_trial_IID_unseen_shift_expected_score": str(forced_count+(problem.length-forced_count)*problem.density),
            "IID_expectation_is_not_a_seeded_confidence_or_best_of_trials_bound": True,
            "classical_hardness_inferred": False, "asymptotic_speedup_established": False}


def diagonal_system(problem):
    """Exact equations; strict lists ALSO require every root nonzero. Not a solver."""
    p, N = problem.prime, problem.length
    _, V = interpolate(p, tuple(range(1, N+1)), (0,)*N)
    derivative = V.derivative()
    multipliers = tuple(pow(int(derivative(x)), -1, p) for x in range(1, N+1))
    rows, targets = [], []
    for j in range(N-problem.dimension):
        h = tuple(multiplier*pow(i+1, j, p) % p for i, multiplier in enumerate(multipliers))
        rows.append(tuple(a*problem.multiplier(i) % p for i, a in enumerate(h)))
        targets.append(-sum(a*t for a, t in zip(h, problem.shifts)) % p)
    return tuple(rows), tuple(targets)


def verify_projective_witness(problem, roots, homogenizer=1):
    """Reject homogeneous points at infinity before claiming a native OPI solution."""
    p = problem.prime
    if (type(roots) is not tuple or len(roots) != problem.length
            or any(type(x) is not int or not 0 <= x < p for x in roots)):
        raise ValueError("canonical native root vector required")
    integer(homogenizer, "projective affine coordinate", 0, p-1)
    rows, rhs = diagonal_system(problem)
    if any(sum(a*pow(x, problem.exponent, p) for a, x in zip(row, roots)) % p
           != b*pow(homogenizer, problem.exponent, p) % p for row, b in zip(rows, rhs)):
        return {"status": "NOT_A_DIAGONAL_SOLUTION", "native_solution": False}
    if homogenizer == 0:
        if not any(roots):
            return {"status": "ZERO_VECTOR_IS_NOT_A_PROJECTIVE_POINT", "native_solution": False}
        return {"status": "POINT_AT_INFINITY_NOT_A_NATIVE_OPI_SOLUTION", "native_solution": False}
    if not problem.include_zero and any(x == 0 for x in roots):
        return {"status": "ZERO_AFFINE_ROOT_EXCLUDED_BY_STRICT_LISTS", "native_solution": False}
    affine = tuple(x*pow(homogenizer, -1, p) % p for x in roots)
    values = tuple((t+problem.multiplier(i)*pow(x, problem.exponent, p)) % p
                   for i, (t, x) in enumerate(zip(problem.shifts, affine)))
    Q, _ = interpolate(p, tuple(range(1, problem.length+1)), values)
    if Q.degree() >= problem.dimension:
        raise ArithmeticError("diagonal system is not equivalent to the native RS code")
    coefficients = tuple(map(int, Q.coeffs()))
    if problem.score_count(coefficients) != problem.length:
        raise ArithmeticError("projective-to-native conversion failed independent Horner checks")
    return {"status": "NATIVE_OPI_SOLUTION", "native_solution": True,
            "polynomial_coefficients_decimal": list(map(str, coefficients)), "score_count": problem.length}


def quantum_reference(problem):
    return {"source": "https://arxiv.org/html/2610.12357#S1.SS2",
            "field_requirement": "PRIME, not binary extension", "density_lower": str(problem.density),
            "published_asymptotic_target": "SCL_rho(R)=(sqrt(rho*(1-R))+sqrt((1-rho)*R))^2 for R<=1-rho; 1 for R>=1-rho",
            "perfect_regime_requires_fixed_positive_gap": "R+rho>1",
            "finite_success_probability_or_score_certificate_supplied": False,
            "coherent_capacity_list_decoder_compiled": False,
            "prime_field_QFT_and_modular_predicates_compiled": False,
            "large_prime_decoder_dependency": "https://eprint.iacr.org/2026/2056",
            "q_to_fixed_power_time_decoder_is_not_poly_log_q": True,
            "random_oracle_hardness_transferred": False}


def strict_root_zero_trap(prime, length, exponent, seed=29):
    """Adversarial exact-power calibration, NOT a putative hard input family."""
    if length % exponent:
        raise ValueError("divisible length required for the exact-power control")
    D = length//exponent
    problem = instance(prime, length, (exponent-1)*D+1, exponent, seed,
                       mode="global", include_zero=False)
    S = (ring(prime).gen()-1)**D
    return replace(problem, shifts=tuple(-pow(int(S(i+1)), exponent, prime) % prime for i in range(length)))


def strict_completion_controls():
    rows = []
    configs = (((1 << 61)-1, 127, 77, 2), ((1 << 61)-1, 63, 46, 3), (998244353, 32, 25, 4))
    for p, N, K, r in configs:
        for seed in (29, 71):
            problem = instance(p, N, K, r, seed, mode="global", include_zero=False)
            rows.append({"source_kind": "strict_common_coset_seeded", "public_seed": seed,
                         "specification": problem.specification(),
                         "completion": complete_positions(problem, tuple(range(N)))})
    for p, N, r in ((5, 4, 2), (7, 6, 3), (13, 8, 4), (17, 16, 8)):
        problem = strict_root_zero_trap(p, N, r)
        rows.append({"source_kind": "adversarial_exact_power_root_zero_control", "public_seed": 29,
                     "specification": problem.specification(),
                     "completion": complete_positions(problem, tuple(range(N)))})
    return rows


def run_controls():
    rows = []
    configs = ((65537, 16, 8, 2), ((1 << 61)-1, 31, 16, 2), ((1 << 61)-1, 127, 39, 2),
               ((1 << 61)-1, 127, 77, 2), ((1 << 61)-1, 63, 46, 3), (998244353, 32, 24, 4))
    for p, N, K, r in configs:
        for seed in (29, 71):
            for mode in ("global", "mixed"):
                problem = instance(p, N, K, r, seed, mode=mode)
                rows.append({"public_seed": seed, "mode": mode, "specification": problem.specification(),
                             "paid_power_completion": attack(problem, seed+10000),
                             "published_quantum_reference_not_finite_certificate": quantum_reference(problem),
                             "all_generated_sources_and_trials_retained": True})
    return {"schema_version": "2.0", "subsystem": "prime_character_opi", "instances": rows,
            "strict_common_coset_controls": strict_completion_controls(),
            "source_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
            "dependency_sha256": {"bpqm_gibbs_frontier.py": hashlib.sha256((PACKAGE/"_validators.py").read_bytes()).hexdigest()},
            "python_flint_version": flint.__version__, "accepted_speedup_candidate": False,
            "new_quantum_algorithm_claimed": False, "mixed_cosets_proved_classically_hard": False,
            "formal_root_attack_novelty_claimed": False, "local_completion_derivation_review_pending": True,
            "literature": ["https://arxiv.org/html/2610.12357", "https://eprint.iacr.org/2026/2056",
                           "https://arxiv.org/html/2609.05870", "https://arxiv.org/abs/1503.09016"]}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true")
    args = parser.parse_args()
    report = run_controls()
    if args.write:
        REPORT.parent.mkdir(parents=True, exist_ok=True)
        REPORT.write_text(json.dumps(report, indent=2)+"\n", encoding="utf-8")
    including_zero_summary = [{"N": r["specification"]["positions"], "K": r["specification"]["RS_dimension"],
                       "power": r["specification"]["power_index"], "seed": r["public_seed"], "mode": r["mode"],
                       "best_score": r["paid_power_completion"]["best_score_count"],
                       "best_mechanism": r["paid_power_completion"]["best_witness_source"],
                       "forced_min_max": [min(len(t["forced_positions"]) for t in r["paid_power_completion"]["trials"]),
                                          max(len(t["forced_positions"]) for t in r["paid_power_completion"]["trials"])]}
                      for r in report["instances"]]
    strict_summary = [{"N": row["specification"]["positions"], "K": row["specification"]["RS_dimension"],
                       "power": row["specification"]["power_index"], "source_kind": row["source_kind"],
                       "score": row["completion"]["score_count"],
                       "root_shift_decimal": row["completion"]["formal_root_certificate"]["zero_avoidance_shift_decimal"]}
                      for row in report["strict_common_coset_controls"]]
    print(json.dumps({"including_zero_controls": including_zero_summary,
                      "strict_common_coset_controls": strict_summary}, indent=2))


if __name__ == "__main__":
    main()
